#include "PluginEditor.h"
CosmosXAudioProcessorEditor::CosmosXAudioProcessorEditor(CosmosXAudioProcessor&p):AudioProcessorEditor(&p),processor(p){
 setSize(680,420); title.setText("ASTORIAS",juce::dontSendNotification);title.setFont(juce::Font(juce::FontOptions(34,juce::Font::bold)));title.setColour(juce::Label::textColourId,juce::Colour(0xffe7f3ff));addAndMakeVisible(title);
 subtitle.setText("POLYPHONIC SYNTHESIZER / VERSION 0.1",juce::dontSendNotification);subtitle.setColour(juce::Label::textColourId,juce::Colour(0xff75cfff));addAndMakeVisible(subtitle);
 auto setup=[this](juce::Slider&s){s.setSliderStyle(juce::Slider::RotaryHorizontalVerticalDrag);s.setTextBoxStyle(juce::Slider::TextBoxBelow,false,76,20);s.setColour(juce::Slider::rotarySliderFillColourId,juce::Colour(0xff39bfff));s.setColour(juce::Slider::textBoxTextColourId,juce::Colour(0xffe7f3ff));s.setColour(juce::Slider::textBoxBackgroundColourId,juce::Colour(0xff101d32));addAndMakeVisible(s);};
 setup(master);setup(cutoff);setup(attack);setup(decay);setup(sustain);setup(release);
 waveform.addItem("SAW",1);waveform.addItem("SQUARE",2);waveform.addItem("SINE",3);addAndMakeVisible(waveform);
 auto&v=processor.parameters;aMaster=std::make_unique<SA>(v,"gain",master);aCutoff=std::make_unique<SA>(v,"cutoff",cutoff);aAttack=std::make_unique<SA>(v,"attack",attack);aDecay=std::make_unique<SA>(v,"decay",decay);aSustain=std::make_unique<SA>(v,"sustain",sustain);aRelease=std::make_unique<SA>(v,"release",release);aWave=std::make_unique<CA>(v,"wave",waveform);
}
void CosmosXAudioProcessorEditor::paint(juce::Graphics&g){g.fillAll(juce::Colour(0xff07101f));juce::ColourGradient bg(juce::Colour(0xff142b49),0,0,juce::Colour(0xff080d19),(float)getWidth(),(float)getHeight(),false);g.setGradientFill(bg);g.fillRoundedRectangle(getLocalBounds().toFloat().reduced(8),16);g.setColour(juce::Colour(0xff39bfff));g.drawLine(28,105,(float)getWidth()-28,105,1);g.setColour(juce::Colour(0xff9bb6d0));g.setFont(12);g.drawText("OSCILLATOR",35,125,130,20,juce::Justification::centredLeft);g.drawText("AMPLITUDE ENVELOPE",35,250,220,20,juce::Justification::centredLeft);g.drawText("MASTER",510,125,100,20,juce::Justification::centred);}
